// Stalwart x:Domain objects.

import { create, destroy, jmap, query, update, type StalwartEnv } from './client'

/** Creates a domain; DKIM keys are generated by Stalwart. Returns its Stalwart id. */
export function createDomain(env: StalwartEnv, name: string): Promise<string> {
  return create(env, 'x:Domain', {
    name,
    certificateManagement: { '@type': 'Manual' },
    dnsManagement: { '@type': 'Manual' },
    subAddressing: { '@type': 'Enabled' },
  })
}

export function setDomainEnabled(env: StalwartEnv, id: string, enabled: boolean): Promise<void> {
  return update(env, 'x:Domain', id, { enable: enabled })
}

/** The domain's DNS records as a zone file, or undefined if Stalwart doesn't have the domain. */
export async function getDnsZone(env: StalwartEnv, id: string): Promise<string | undefined> {
  const [result] = await jmap(env, [['x:Domain/get', { ids: [id], properties: ['dnsZoneFile'] }]])
  return (result?.list as { dnsZoneFile?: string }[] | undefined)?.[0]?.dnsZoneFile
}

/** Deletes the domain and its DKIM keys. Stalwart refuses (objectIsLinked) while the keys still exist. */
export async function destroyDomain(env: StalwartEnv, id: string): Promise<void> {
  await destroy(env, 'x:DkimSignature', await query(env, 'x:DkimSignature', { domainId: id }))
  await destroy(env, 'x:Domain', id)
}
